    def _change_mood(self):
        mood = simpledialog.askstring(
            "Set Mood",
            "Enter mood hint for Rem (e.g. 'battle mode', 'shy', 'happy'):",
            parent=self
        )
        if mood:
            self.current_mood = mood.strip().capitalize()
            self.session.mood_hint = mood.strip()
            self.mood_btn.config(text=f"  {self.current_mood} —  ")
            self.avatar_status.config(
                text=f"✦ {self.current_mood.lower()} [idle] ✦")

    def _open_settings(self):
        win = tk.Toplevel(self)
        win.title("⚙ Settings")
        win.configure(bg=BG_DARK)
        win.geometry("340x280")
        win.resizable(False, False)

        def row(label, var, row_n):
            tk.Label(win, text=label, bg=BG_DARK, fg="#ffffff",
                     font=("Segoe UI", 10)).grid(
                row=row_n, column=0, padx=16, pady=8, sticky="w")
            e = tk.Entry(win, textvariable=var, bg=INPUT_BG, fg="#ffffff",
                         insertbackground="#ffffff", relief=tk.FLAT, width=18)
            e.grid(row=row_n, column=1, padx=16, pady=8)

        temp_var  = tk.StringVar(value=str(self.session.temperature))
        tok_var   = tk.StringVar(value=str(self.session.max_tokens))
        hist_var  = tk.StringVar(value=str(self.session.max_history))
        model_var = tk.StringVar(value=self.session.model)

        row("Temperature:", temp_var, 0)
        row("Max Tokens:",  tok_var,  1)
        row("History:",     hist_var, 2)
        row("Model:",       model_var, 3)

        def save():
            try:
                self.session.temperature = float(temp_var.get())
                self.session.max_tokens  = int(tok_var.get())
                self.session.max_history = int(hist_var.get())
                self.session.model       = model_var.get().strip()
                win.destroy()
                self.status_var.set("Settings saved.")
            except ValueError:
                messagebox.showerror("Error", "Invalid value.", parent=win)

        tk.Button(win, text="Save", bg=BUTTON_SEND, fg="#ffffff",
                  relief=tk.FLAT, font=("Segoe UI", 10, "bold"),
                  padx=16, pady=6, command=save,
                  cursor="hand2").grid(row=4, column=0, columnspan=2, pady=12)

